pm.test("Verificar que la respuesta sea 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Verificar que el tiempo de respuesta sea menor a 1000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

pm.test("Verificar que el body no esté vacío", function () {
    pm.expect(pm.response.text().length).to.be.greaterThan(0);
});

pm.test("Verificar que exista el header Content-Type", function () {
    pm.response.to.have.header("Content-Type");
});

pm.test("Verificar tamaño de respuesta razonable", function () {
    pm.expect(pm.response.responseSize).to.be.below(100000);
});
